{"command": "cat > /testbed/fix_sdm2.py << 'EOF'
with open('/testbed/pvlib/ivtools/sdm.py', 'r') as f:
    content = f.read()

# Replace the import with a local implementation
old_import = '''try:
    from scipy.misc import derivative
except ImportError:
    from scipy.optimize import derivative'''

new_import = '''try:
    from scipy.misc import derivative
except ImportError:
    try:
        from scipy.optimize import derivative
    except ImportError:
        # scipy >= 1.12.0 removed derivative, define our own
        import numpy as np
        def derivative(func, x0, dx=1.0, n=1, args=(), order=3):
            if n != 1:
                raise NotImplementedError("Only n=1 is supported")
            if order != 3:
                raise NotImplementedError("Only order=3 is supported")
            # Central difference formula
            return (func(x0 + dx, *args) - func(x0 - dx, *args)) / (2.0 * dx)'''

if old_import in content:
    content = content.replace(old_import, new_import)
    with open('/testbed/pvlib/ivtools/sdm.py', 'w') as f:
        f.write(content)
    print("Fixed!")
else:
    print("Pattern not found")
EOF
python /testbed/fix_sdm2.py"}

